<x-app-layout title="Laporan" module="reports" :module-data="config('modules.reports')"><div><p class="text-sm font-semibold text-brand-700">Laporan</p><h1 class="mt-1 text-2xl font-semibold">Ringkasan Operasional</h1><p class="mt-2 text-sm text-slate-500">Angka sederhana untuk memantau operasi perusahaan.</p></div><form method="GET" class="mt-7 grid gap-4 rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-3"><x-ui.input label="Tanggal Mulai" name="start_date" type="date" :value="$startDate" required /><x-ui.input label="Tanggal Akhir" name="end_date" type="date" :value="$endDate" required /><div class="flex items-end"><x-ui.button type="submit" variant="secondary" class="w-full">Tampilkan</x-ui.button></div></form><section class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><x-ui.stat-card label="Penjualan" :value="'Rp '.number_format((float) $salesTotal, 0, ',', '.')" tone="blue" /><x-ui.stat-card label="Pembelian diterima" :value="'Rp '.number_format((float) $purchaseTotal, 0, ',', '.')" tone="orange" /><x-ui.stat-card label="Hasil produksi" :value="number_format((float) $productionTotal, 0, ',', '.').' karton'" tone="green" /><x-ui.stat-card label="Uang masuk" :value="'Rp '.number_format((float) $cashIn, 0, ',', '.')" tone="green" /><x-ui.stat-card label="Uang keluar" :value="'Rp '.number_format((float) $cashOut, 0, ',', '.')" tone="red" /><x-ui.stat-card label="Arus kas bersih" :value="'Rp '.number_format((float) $cashIn - (float) $cashOut, 0, ',', '.')" tone="blue" /></section><section class="mt-6 grid gap-4 sm:grid-cols-2"><x-ui.stat-card label="Total piutang berjalan" :value="'Rp '.number_format((float) $receivableTotal, 0, ',', '.')" tone="orange" /><x-ui.stat-card label="Total hutang berjalan" :value="'Rp '.number_format((float) $payableTotal, 0, ',', '.')" tone="orange" /></section><p class="mt-6 rounded-xl bg-slate-100 p-4 text-sm text-slate-600">Ringkasan ini bukan laporan laba rugi formal. Nilai menampilkan transaksi penjualan, penerimaan pembelian, kas, piutang, dan hutang.</p></x-app-layout>
